pub fn all_sequence_equal_length(seq: &Vec<Vec<i32>>) -> bool {
    // If the outer list is empty (although the problem states it won't be),
    // we can consider all lengths trivially equal.
    if seq.is_empty() {
        return true;
    }

    // Grab the length of the first inner array to compare against.
    let first_len = seq[0].len();

    // Check that every inner array has the same length.
    seq.iter().all(|inner| inner.len() == first_len)
}